$ErrorActionPreference='Stop'
function M([string]$name,[string]$what,[string[]]$inv,[string]$fp,$consts,[string[]]$ev,[string[]]$mods){
  [ordered]@{ name=$name; what=$what; invariants=$inv; failurePolicy=$fp; constants=$consts; evidence=$ev; modules=$mods; verified=$true }
}
function C([string]$n,[string]$v,[string]$e){ [ordered]@{ name=$n; value=$v; evidence=$e } }

$model=@(
 (M 'api-protocol-selection-and-adapter-contract' `
  'Declares the two supported wire protocols (ApiProtocol = ''messages'' | ''responses'', i.e. Anthropic /v1/messages vs OpenAI /v1/responses) plus a ProtocolAdapter interface with capability reporting, request-body building, stream-event conversion, usage extraction and stop-reason extraction, over a protocol-neutral IR (ProtocolConversationItem, ProtocolStreamEvent, ProtocolUsage). Runtime selection is a three-level chain: in-memory runtime override, then CLAUDE_CODE_PROTOCOL parsed by literal match (not truthiness), then the default ''messages''; queryModel dispatches early to the Responses slice and logs which source won. The /protocol command writes through onChangeAppState to userSettings and mirrors into the env var.' `
  @('messages is the stable default; responses is opt-in only and must not become the default silently','Adapters must not leak Anthropic-only fields (cache_control, betas, speed, context_management) into non-Anthropic request bodies') `
  'mixed - an invalid CLAUDE_CODE_PROTOCOL value falls back to messages (fail-soft, protocolState.ts:52-55), but getProtocolClient() throws outright if called while the active protocol is responses (fail-closed, client.ts:374-380)' `
  @((C 'ApiProtocol union' "'messages' | 'responses'" 'src/services/api/protocol.ts:26'),(C 'default protocol' "'messages'" 'src/utils/protocol/protocolState.ts:82')) `
  @('src/services/api/protocol.ts:26','src/services/api/protocol.ts:39-48,91-121','src/services/api/protocolTypes.ts:23-28,75-83','src/utils/protocol/protocolState.ts:52-83','src/services/api/claude.ts:706-728','src/services/api/client.ts:363-381','src/state/onChangeAppState.ts:79-81') `
  @('src/services/api/protocol.ts','src/services/api/protocolTypes.ts','src/utils/protocol/protocolState.ts','src/state/onChangeAppState.ts')),

 (M 'messages-request-assembly-and-beta-gating' `
  'buildMessagesRequest() is the single assembler for the Anthropic /v1/messages body: cache breakpoints on the last message (or second-to-last when skipCacheWrite), system-prompt blocks with per-block cache_control, adaptive-vs-budget thinking config clamped below max_tokens, effort and task_budget folded into output_config, structured-output format, fast-mode speed, optional context_management, and Bedrock extra-body params. Beta headers are computed per model by a memoized getAllModelBetas() that branches on provider (firstParty/bedrock/vertex/foundry) and canonical model family, then STRIPPED for non-first-party endpoints by a prefix allowlist before hitting the wire.' `
  @('max_tokens > thinking.budget_tokens must hold - the budget is clamped to maxOutputTokens-1','At most one cache breakpoint per request (last, or length-2 when skipCacheWrite)') `
