  @((C 'CAPPED_DEFAULT_MAX_TOKENS' '8000' 'src/utils/context.ts:25'),(C 'MAX_OUTPUT_TOKENS_UPPER_LIMIT' '64000' 'src/utils/context.ts:17'),(C 'EFFORT_BETA_HEADER' "'effort-2025-11-24'" 'src/constants/betas.ts:15'),(C 'THIRD_PARTY_ALLOWED_BETA_PREFIXES' "claude-code-, interleaved-thinking-, effort-, structured-outputs-, advanced-tool-use-, tool-search-tool-" 'src/utils/betas.ts:432-439')) `
  @('src/services/api/adapters/messagesAdapter.ts:409-441,476-491,528-612,650-719','src/utils/betas.ts:228-348,441-448','src/constants/betas.ts:34-48','src/services/api/claude.ts:245-276') `
